PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_meta(version INTEGER NOT NULL,applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,subtitle TEXT,destination TEXT,start_date TEXT,end_date TEXT,welcome_message TEXT,host_lodging_status TEXT DEFAULT 'Not booked yet',host_hotel TEXT,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT,last_login_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_memberships(event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'guest' CHECK(role IN('organizer','guest')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS hotels(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,name TEXT NOT NULL,room_type TEXT,area TEXT DEFAULT 'Oak Bluffs',nightly_rate REAL,booking_url TEXT,notes TEXT,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS budget_items(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,label TEXT NOT NULL,detail TEXT,amount_text TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,location TEXT,event_date TEXT,event_time TEXT,cost_text TEXT,status TEXT NOT NULL DEFAULT 'published',category TEXT,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_ideas(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,title TEXT NOT NULL,category TEXT,description TEXT,suggested_date TEXT,suggested_time TEXT,meeting_place TEXT,status TEXT NOT NULL DEFAULT 'approved',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_responses(activity_id INTEGER NOT NULL REFERENCES activity_ideas(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,response TEXT NOT NULL CHECK(response IN('going','interested')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(activity_id,user_id));
CREATE TABLE IF NOT EXISTS guest_book_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_sections(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,key TEXT NOT NULL,label TEXT NOT NULL,value TEXT,UNIQUE(event_id,key));
CREATE TABLE IF NOT EXISTS photos(id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),object_key TEXT NOT NULL,caption TEXT,status TEXT NOT NULL DEFAULT 'published',content_type TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_hotels_event ON hotels(event_id);CREATE INDEX IF NOT EXISTS idx_costs_event ON budget_items(event_id);CREATE INDEX IF NOT EXISTS idx_activities_event ON activities(event_id);CREATE INDEX IF NOT EXISTS idx_ideas_event ON activity_ideas(event_id);CREATE INDEX IF NOT EXISTS idx_announcements_event ON announcements(event_id);
